SourceCode.Declaration:
/// <summary>
/// Helper class for managing business event skipping based on controlled field changes.
/// Determines whether business events should be skipped by checking if any controlled fields
/// have been modified in the current record.
/// </summary>
public class METCheckSkipBusinessEventsHelper
{
}

Method.Source:
/// <summary>
/// Checks if business events should be skipped based on controlled field modifications.
/// </summary>
/// <param name="_common">The common record to evaluate for controlled field changes.</param>
/// <remarks>
/// This method queries the METDualWriteControlledFields table for the given table and
/// checks if any of the specified controlled fields have been modified. If no controlled
/// fields have changed, business events will be skipped.
/// </remarks>
public static void shouldSkipBusinessEvents(common _common)
{
    boolean isDualWriteFieldModified;
    container controlledFieldContainer;
    METDualWriteControlledFields metDualWriteControlledFields = METDualWriteControlledFields::find(tableId2Name(_common.TableId));

    if (metDualWriteControlledFields.RecId && metDualWriteControlledFields.DoNotUse == NoYes::No)
    {
        Common orig = _common.orig();
        controlledFieldContainer = str2con(metDualWriteControlledFields.ListOfFields, ',');

        for (int i = 1; i <= conLen(controlledFieldContainer); i++)
        {
            str fieldName = conPeek(controlledFieldContainer, i);
            FieldId fieldId = fieldName2Id(_common.TableId, fieldName);

            if (fieldId && (orig.(fieldId) != _common.(fieldId)))
            {
                isDualWriteFieldModified = true;
                break;
            }
        }

        if (!isDualWriteFieldModified)
        {
            _common.skipBusinessEvents(true);
        }

    }

}
